            if(helperService.isBranch2Scan(request, branches)){
                flowService.initiateAutomation(request);
            }

        }
        catch (IllegalArgumentException e){
            return getBadRequestMessage(e, controllerRequest, product);
        }

        return getSuccessMessage();
    }
