			v2_signing_status = block_valid ? VALID : INVALID;
		} else if (id == 0xf05368c0u) {
			block_valid = check_block(fp, &size4, &pos, &offset,
						  expected_size, expected_sha256);
			v3_signing_status = block_valid ? VALID : INVALID;
		}
		pos += (size8 - offset);
